/* Work is a second page, sharing Home's language and visual primitives. */
const homePageRender=render;
icons.work='<rect x="4" y="6" width="16" height="15" rx="3"/><path d="M9 6V3h6v3M8 11h8M8 15h5"/>';
const workState={confirmed:[],analysisReady:false,newId:null};
const tasks={reply:{title:['Early arrival request','提前入住咨询'],meta:['Room 102 · Alex','102 房 · Alex'],note:['AI has prepared a reply.','AI 已准备好回复。'],cta:['Review reply','审核回复'],draft:['Hi Alex, our usual check-in time is 14:00. We can check whether Room 102 will be ready earlier on your arrival day. You are welcome to leave your luggage with us in the meantime.','Alex，你好！我们的常规入住时间是 14:00。抵达当天，我们可以确认 102 房是否能提前准备好。等待期间，你可以先寄存行李。'],source:['Based on your sample check-in policy. Early check-in is not guaranteed.','依据示例入住规则。未承诺一定能提前入住。']},promotion:{title:['Weekday promotion','工作日推广'],meta:['Based on your recent occupancy','依据近期入住率'],note:['Draft is ready for review.','草稿已准备好，等待审核。'],cta:['Review draft','审核草稿'],draft:['A little more room to slow down. Enjoy a quieter weekday escape at Garden House — a comfortable stay and time to explore at your own pace. Ask us about available midweek dates.','给生活多一点留白。在花园民宿享受安静的工作日小住，舒适休息，按自己的节奏探索周边。欢迎咨询工作日可订日期。'],source:['Based on sample occupancy: weekdays have more availability. No discount or publishing is assumed.','依据示例入住率：工作日空房较多。未设定优惠或自动发布。']},analysis:{title:['Weekday occupancy insight','工作日入住率洞察'],meta:['Sample booking records · This week','示例预订记录 · 本周'],note:['Your insight is ready to review.','分析已准备好，等待查看。'],cta:['Review insight','查看分析'],draft:['Weekday occupancy averages 64%, compared with 85% at the weekend. Consider a midweek stay offer; review your costs before deciding on any discount.','工作日平均入住率为 64%，周末为 85%。可考虑工作日住宿推广；决定折扣前请先核对成本。'],source:['Sample: 32 / 50 weekday room nights and 17 / 20 weekend room nights. This is not a market forecast.','示例：工作日 32 / 50 间夜，周末 17 / 20 间夜。不代表市场预测。']}};
const tx=a=>tr(...a);
const pending=()=>['reply','promotion',...(workState.analysisReady?['analysis']:[])].filter(id=>!workState.confirmed.includes(id));
const baseActivity=[{id:'prepared',time:'14:32',title:['Guest reply prepared','客人回复已准备'],sub:['Early arrival · Room 102 · Awaiting review','提前入住 · 102 房 · 待审核']},{id:'breakfast',time:'13:18',title:['Property information updated','民宿资料已更新'],sub:['Archived sample · Breakfast time','历史示例 · 早餐时间']},{id:'weekly',time:'11:46',title:['Weekly insight generated','每周分析已生成'],sub:['Weekday occupancy is lower','工作日入住率较低']}];
const completedItems=()=>workState.confirmed.slice().reverse().map(id=>({id:'confirmed-'+id,time:'14:45',title:[id==='reply'?'Guest reply confirmed':id==='promotion'?'Promotion draft approved':'Occupancy insight reviewed',id==='reply'?'客人回复已确认':id==='promotion'?'推广草稿已确认':'入住率分析已查看'],sub:[id==='reply'?'Saved · Not sent':id==='promotion'?'Saved · Not published':'Reviewed · No pricing changes',id==='reply'?'已保存 · 未发送':id==='promotion'?'已保存 · 未发布':'已查看 · 未调整价格']}));
function navWork(){const entries=[['home','home','Home','首页'],['work','work','Work','工作'],['insight','insight','Analysis','分析'],['explore','explore','Explore','探索'],['profile','profile','My Homestay','我的民宿']];document.getElementById('dock').innerHTML=entries.map(([key,icon,en,zh])=>`<button class="tab ${page===(key==='insight'?'analysis':key)?'active':''}" data-open="${key}" aria-label="${tr(en,zh)}" title="${tr(en,zh)}" ${page===(key==='insight'?'analysis':key)?'aria-current="page"':''}><span class="navicon">${svg(icon)}</span></button>`).join('');}
let page=location.hash.startsWith('#work')?'work':location.hash.startsWith('#analysis')?'analysis':location.hash.startsWith('#explore')?'explore':location.hash.startsWith('#profile')?'profile':'home';
function goPage(next){if(page===next){window.scrollTo({top:0,behavior:motion()?'smooth':'instant'});return;}location.hash=next;}
function motion(){return !matchMedia('(prefers-reduced-motion: reduce)').matches;}
function activityRow(item){return `<li class="activity-row ${workState.newId===item.id?'just-added':''}"><span class="activity-time">${item.time}</span><span class="activity-check" aria-hidden="true">✓</span><button class="activity-content" data-activity="${item.id}"><strong>${tx(item.title)}</strong><span>${escapeHtml(tx(item.sub))}</span></button></li>`;}
function taskPanel(id){const t=tasks[id];return `<article class="review-panel ${id==='promotion'?'promotion-panel':''}" id="task-${id}"><span class="task-type">${svg(id==='reply'?'reply':id==='analysis'?'insight':'content')}${tr(id==='reply'?'GUEST CARE':id==='analysis'?'ANALYSIS':'CONTENT',id==='reply'?'客人服务':id==='analysis'?'经营分析':'内容推广')}</span><h3>${tx(t.title)}</h3><p class="task-meta">${tx(t.meta)}</p><p class="task-note">${tx(t.note)}</p><button class="review-trigger" data-review="${id}" aria-expanded="false" aria-controls="review-${id}">${tx(t.cta)} ${svg('arrow')}</button><div class="review-expansion" id="review-${id}" inert><div><div class="review-inner"><label for="draft-${id}">${tr('AI draft · Sample','AI 草稿 · 示例')}</label><textarea id="draft-${id}" rows="5" ${id==='analysis'?'readonly':''}>${tx(t.draft)}</textarea><p class="draft-source">${tx(t.source)}</p><button class="confirm-task" data-confirm="${id}">${tr(id==='analysis'?'Mark as reviewed':'Confirm & save',id==='analysis'?'标记为已查看':'确认并保存')} ${svg('arrow')}</button><p class="confirm-note">${tr('Demo only. Nothing is sent or published.','仅供演示，不会发送或发布内容。')}</p></div></div></div></article>`;}
function renderWork(){const ids=pending();document.getElementById('app').innerHTML=`<div class="work-page"><header class="work-header"><div class="work-topline"><span class="sample-label">${tr('SAMPLE WORKSPACE','示例工作区')}</span><button id="work-language">${tr('中文','EN')}</button></div></header><section class="work-summary work-brief" aria-label="${tr('AI work summary','AI 工作摘要')}"><p class="brief-intro">${tr('While you were away,','你不在的时候，')}</p><p class="brief-main">${tr('AI completed','AI 已完成')} <strong>${baseActivity.length+(workState.analysisReady?1:0)}</strong> ${tr('tasks.','项工作。')}</p><p class="brief-review">${ids.length?tr(`${ids.length} ${ids.length===1?'is':'are'} ready for your review.`,`${ids.length} 项等待你确认。`):tr('You’re all caught up.','所有待确认事项都已处理。')}</p></section><section aria-labelledby="needs-title"><div class="work-heading"><h2 id="needs-title">${tr('Needs you','待你确认')}</h2><span class="work-count">${ids.length.toString().padStart(2,'0')}</span></div><div id="review-list">${ids.length?ids.map(taskPanel).join(''):`<p class="all-clear">${tr('All caught up. Your AI team will bring the next decision here.','都处理好了。新的确认事项会出现在这里。')}</p>`}</div></section><section class="working-section" aria-labelledby="working-title"><div class="work-heading"><h2 id="working-title">${tr('Working','正在处理')}</h2><span class="quiet-dots" aria-hidden="true"><i></i><i></i><i></i></span></div>${!workState.analysisReady?`<div class="working-task"><div class="working-orbit" aria-hidden="true">${svg('insight')}</div><div><h3>${tr('Analysing this week’s bookings','正在分析本周预订')}</h3><p>${tr('Looking for changes in weekday occupancy.','正在寻找工作日入住率的变化。')}</p></div></div><div class="progress-track" aria-hidden="true"><span></span></div><button class="demo-progress" id="advance-demo">${tr('Demo: finish analysis','演示：完成分析')} ${svg('arrow')}</button>`:`<p class="quiet-copy">${tr('Nothing running right now. The latest insight is ready.','当前没有处理中任务，最新分析已准备好。')}</p>`}</section><section class="done-section" aria-labelledby="done-title"><div class="work-heading"><h2 id="done-title" tabindex="-1">${tr('Done','已完成')}</h2><span class="done-caption">${tr('AI work & your decisions','AI 工作与确认记录')}</span></div><p class="timeline-day">${tr('TODAY','今天')}</p><ol class="activity-list">${[...(typeof propertyActivities==='function'?propertyActivities():[]),...completedItems(),...baseActivity].map(activityRow).join('')}</ol><p class="timeline-day">${tr('YESTERDAY','昨天')}</p><ol class="activity-list">${activityRow({id:'saved',time:'18:20',title:['Promotion draft saved','推广草稿已保存'],sub:['Midweek stay offer','工作日住宿推广']})}</ol></section><footer class="work-footer"><p>${tr('Sample data · No connected booking platforms','示例数据 · 未连接预订平台')}</p><button id="reset-work">${tr('Reset demo','重置演示')}</button></footer></div>`;document.getElementById('work-language').onclick=()=>{lang=lang==='en'?'zh':'en';render()};document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>toggleReview(b));document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>confirmTask(b.dataset.confirm));document.getElementById('advance-demo')?.addEventListener('click',()=>{workState.analysisReady=true;render();announce(tr('Analysis is ready for your review.','分析已完成，等待你查看。'));document.getElementById('task-analysis').scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'})});document.getElementById('reset-work').onclick=()=>{workState.confirmed=[];workState.analysisReady=false;workState.newId=null;Object.keys(savedDrafts).forEach(k=>delete savedDrafts[k]);render();announce(tr('Demo reset.','演示已重置。'))};bindActivity();}
const savedDrafts={};
function toggleReview(b){const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));const pane=document.getElementById(b.getAttribute('aria-controls'));pane.inert=!open;pane.classList.toggle('is-open',open);if(open){const field=pane.querySelector('textarea');field.value=savedDrafts[b.dataset.review]||field.value;field.oninput=()=>savedDrafts[b.dataset.review]=field.value;}}
async function confirmTask(id){if(workState.confirmed.includes(id))return;const field=document.getElementById('draft-'+id);if(!field.value.trim()){field.setCustomValidity(tr('Please add a reply or draft.','请输入内容。'));field.reportValidity();field.oninput=()=>field.setCustomValidity('');return;}savedDrafts[id]=field.value;const panel=document.getElementById('task-'+id);panel.querySelector('[data-confirm]').disabled=true;if(motion())await panel.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(18px)'}],{duration:220,easing:'ease-in',fill:'forwards'}).finished;workState.confirmed.push(id);workState.newId='confirmed-'+id;render();announce(tr('Confirmed and added to Done. Nothing was sent or published.','已确认并加入完成记录，未发送或发布。'));document.getElementById('done-title').focus({preventScroll:true});document.querySelector('.just-added')?.scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'});}
const sheet=document.createElement('dialog');sheet.className='activity-sheet';sheet.setAttribute('aria-labelledby','activity-title');document.body.append(sheet);sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)sheet.close()}});
function showActivity(id){const breakfast=id==='breakfast';const confirmed=id.startsWith('confirmed-');const task=confirmed?tasks[id.slice(10)]:null;sheet.innerHTML=`<div class="sheet-close-row"><span class="sample-label">${tr('SAMPLE ACTIVITY','示例记录')}</span><button class="round" aria-label="${tr('Close','关闭')}" id="activity-close">×</button></div><h2 id="activity-title">${breakfast?tr('Breakfast time updated','早餐时间已更新'):confirmed?tx(task.title):tx([...baseActivity,{id:'saved',title:['Promotion draft saved','推广草稿已保存']}].find(x=>x.id===id).title)}</h2>${breakfast?`<div class="change-comparison"><div><span>${tr('Previous','之前')}</span><p>07:00–10:00</p></div><div><span>${tr('New','现在')}</span><p>07:30–10:00</p></div></div><p class="saved-location">${tr('Saved to My Homestay','已保存至我的民宿')}</p><button class="confirm-task" id="view-property">${tr('View property','查看民宿')} ${svg('arrow')}</button>`:`<p class="activity-description">${confirmed?escapeHtml(savedDrafts[id.slice(10)]):tr(id==='prepared'?'Reply prepared, awaiting your review. Nothing has been sent.':id==='weekly'?'Sample bookings show lower weekday occupancy. No prices were changed.':'Your midweek stay draft is saved for review. It has not been published.',id==='prepared'?'回复已准备，等待你审核。未发送。':id==='weekly'?'示例预订显示工作日入住率较低。未调整价格。':'工作日推广草稿已保存，等待审核。未发布。')}</p><p class="confirm-note">${tr('Prototype history · Sample data only','原型记录 · 仅示例数据')}</p>`}`;sheet.querySelector('#activity-close').onclick=()=>sheet.close();sheet.querySelector('#view-property')?.addEventListener('click',()=>{sheet.querySelector('#activity-title').textContent=tr('My Homestay · Preview','我的民宿 · 预览');sheet.querySelector('.change-comparison').innerHTML=`<div><span>Garden House</span><p>${tr('Breakfast','早餐')} 07:30–10:00</p></div>`;sheet.querySelector('.saved-location').textContent=tr('Sample property details. Full page coming later.','示例民宿资料，完整页面后续设计。');sheet.querySelector('#view-property').remove()});sheet.showModal();}
function escapeHtml(s){const el=document.createElement('div');el.textContent=s;return el.innerHTML;}
function bindActivity(){document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>showActivity(b.dataset.activity));}
const live=document.createElement('div');live.className='work-toast';live.setAttribute('role','status');document.body.append(live);let toastTimer;
function announce(message){live.textContent=message;live.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>live.classList.remove('visible'),4200);}
function patchHome(){const cards=[...document.querySelectorAll('.work-card')];const ids=pending().filter(id=>id!=='analysis');cards.forEach((card,i)=>{const id=['reply','promotion'][i];if(!ids.includes(id)){card.remove();return;}card.querySelector('h3').textContent=tx(tasks[id].title);card.querySelector('.sub').textContent=id==='reply'?tr('AI reply ready','AI 回复已准备'):tr('Draft ready','草稿已准备');const b=card.querySelector('.action');b.removeAttribute('data-open');b.innerHTML=tr('Review','审核')+svg('arrow');b.onclick=()=>{location.hash='work/'+id}});const heading=[...document.querySelectorAll('.section-title')].find(h=>h.textContent.includes(tr('Ready when you are','待你处理')));if(heading)heading.querySelector('small').textContent=tr(`${ids.length} items`,`${ids.length} 项`);document.querySelector('.footer').insertAdjacentHTML('beforebegin',`<section class="home-activity"><h2>${tr('Recently completed','最近完成')}</h2><button data-activity="breakfast">✓ ${tr('Breakfast information updated','早餐资料已更新')} <span>13:18</span></button><button data-activity="weekly">✓ ${tr('Weekly analysis ready','每周分析已准备')} <span>11:46</span></button><button class="all-activity">${tr('View all activity','查看全部记录')} ${svg('arrow')}</button></section>`);document.querySelector('.all-activity').onclick=()=>goPage('work');bindActivity();}
render=function(){if(typeof cleanupAnalysis==='function')cleanupAnalysis();revealObserver?.disconnect();const old=document.getElementById('app');old.replaceWith(old.cloneNode(false));document.getElementById('app').classList.toggle('is-work',page==='work');document.getElementById('app').classList.toggle('is-analysis',page==='analysis');document.getElementById('app').classList.toggle('is-explore',page==='explore');document.getElementById('app').classList.toggle('is-profile',page==='profile');document.documentElement.lang=lang==='en'?'en':'zh-CN';if(page==='home'){homePageRender();patchHome();if(typeof mountHomeAssistant==='function')mountHomeAssistant()}else if(page==='analysis'&&typeof renderAnalysis==='function')renderAnalysis();else if(page==='work')renderWork();else if(page==='explore'&&typeof renderExplore==='function')renderExplore();else if(page==='profile'&&typeof renderProperty==='function')renderProperty();navWork();document.querySelectorAll('#dock [data-open]').forEach(b=>{const k=b.dataset.open;if(k==='home'||k==='work'||k==='insight'||k==='explore'||k==='profile')b.onclick=()=>goPage(k==='insight'?'analysis':k);else b.onclick=()=>{document.getElementById('modal-title').textContent=b.getAttribute('aria-label');document.getElementById('modal-copy').textContent=tr('This page will be designed next. This prototype currently includes Home, Work, Analysis and Explore.','此页面后续设计，当前原型包含首页、工作区、分析与探索页。');document.getElementById('modal-ok').textContent=tr('Close','关闭');document.getElementById('modal').showModal()}});document.querySelectorAll('#app [data-open=insight]').forEach(b=>b.onclick=()=>goPage('analysis'));document.querySelectorAll('#app [data-open=profile]').forEach(b=>b.onclick=()=>goPage('profile'));document.title='Homestay AI · '+(page==='profile'?'My Homestay':page==='explore'?'Explore':page==='analysis'?'Analysis':page==='work'?'Work':'Home');if(page==='work'){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('arrived');observer.unobserve(e.target)}}),{threshold:.05});document.querySelectorAll('.activity-row').forEach(e=>observer.observe(e));revealObserver=observer;}const review=location.hash.split('/')[1];if(page==='work'&&review){const b=document.querySelector(`[data-review="${review}"]`);if(b){toggleReview(b);b.scrollIntoView({block:'center'})}}};
window.addEventListener('hashchange',()=>{page=location.hash.startsWith('#work')?'work':location.hash.startsWith('#analysis')?'analysis':location.hash.startsWith('#explore')?'explore':location.hash.startsWith('#profile')?'profile':'home';render();if(!location.hash.includes('/'))window.scrollTo(0,0)});
render();






